#!/usr/bin/env sh
# Creates .env for docker compose with freshly generated secrets.
# Safe to re-run: an existing .env is never overwritten.
set -eu

cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists; leaving it unchanged."
  exit 0
fi

rand_hex() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex "$1"
  else
    od -An -tx1 -N"$1" /dev/urandom | tr -d ' \n'
  fi
}

cat > .env <<ENV
# Generated by scripts/init-env.sh. Keep this file private and backed up:
# GATEWAY_SECRET_KEY encrypts stored credentials, and data encrypted with it
# cannot be read with a different key.
JWT_SECRET=$(rand_hex 32)
API_KEY=igw_$(rand_hex 24)
GATEWAY_SECRET_KEY=$(rand_hex 32)

# Public URL people use to open the console (used in links and CORS).
FRONTEND_URL=http://localhost
ENV

chmod 600 .env
echo "Created .env with random secrets."
echo "Next: docker compose up -d --build"
